import{af as s,z as a,J as t,ab as i}from"./chunks/framework.BnTFvF69.js";const h=JSON.parse('{"title":"Setup SQS Notifications","description":"","frontmatter":{"aside":false,"outline":false,"sidebar":false},"headers":[],"relativePath":"guides/notifications-setup-sqs.md","filePath":"guides/notifications-setup-sqs.md"}'),o={name:"guides/notifications-setup-sqs.md"};function n(r,e,u,l,c,p){return a(),t("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793203908000"},[...e[0]||(e[0]=[i(`<h1 id="setup-sqs-notifications" tabindex="-1">Setup SQS Notifications <a class="header-anchor" href="#setup-sqs-notifications" aria-label="Permalink to &quot;Setup SQS Notifications&quot;">​</a></h1><p>This guide explains how to register an AWS SQS queue to receive device notifications via our platform.</p><p>Under the hood, this uses AWS SNS (Simple Notification Service) to deliver the notifications to your endpoint, which in turn has its <a href="https://docs.aws.amazon.com/sns/latest/dg/subscribe-sqs-queue-to-sns-topic.html" target="_blank" rel="noreferrer">own documentation</a>.</p><p>This page acts as a Lightbug specific summary of those steps, and how to set up your endpoint to receive the notifications.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>An AWS account with permissions to create and manage SQS queues and policies.</li><li>An SQS queue created in your AWS account.</li></ul><h2 id="_1-queue-policy" tabindex="-1">1. Queue Policy <a class="header-anchor" href="#_1-queue-policy" aria-label="Permalink to &quot;1. Queue Policy&quot;">​</a></h2><p>Your SQS queue must allow our platform (via AWS SNS) to send messages.</p><p>Replace <code>YOUR_SQS_ARN</code> with your queue&#39;s ARN in both the policy and the code.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;Version&quot;: &quot;2012-10-17&quot;,</span></span>
<span class="line"><span>    &quot;Id&quot;: &quot;AllowLightbugPush&quot;,</span></span>
<span class="line"><span>    &quot;Statement&quot;: [</span></span>
<span class="line"><span>     {</span></span>
<span class="line"><span>        &quot;Sid&quot;: &quot;AllowLightbugPush001&quot;,</span></span>
<span class="line"><span>        &quot;Effect&quot;: &quot;Allow&quot;,</span></span>
<span class="line"><span>        &quot;Principal&quot;: &quot;*&quot;,</span></span>
<span class="line"><span>        &quot;Action&quot;: &quot;sqs:SendMessage&quot;,</span></span>
<span class="line"><span>        &quot;Resource&quot;: &quot;YOUR_SQS_ARN&quot;,</span></span>
<span class="line"><span>        &quot;Condition&quot;: {</span></span>
<span class="line"><span>            &quot;ArnEquals&quot;: {</span></span>
<span class="line"><span>                &quot;aws:SourceArn&quot;: &quot;arn:aws:sns:*:367158939173:*&quot;</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>     }</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>See <a href="https://docs.aws.amazon.com/sns/latest/dg/SendMessageToSQS.cross.account.html" target="_blank" rel="noreferrer">AWS docs</a> for more details.</p><h2 id="_2-notification-trigger" tabindex="-1">2. Notification Trigger <a class="header-anchor" href="#_2-notification-trigger" aria-label="Permalink to &quot;2. Notification Trigger&quot;">​</a></h2><p>You can register your SQS queue to receive notifications <a href="/docs/pr/30/apis/v1/get-devices-id-setupSqsForwarding">using the API</a>.</p><p>You need to specify the device ID and <code>sqsArn</code> as well as an optional collection of types.</p><div class="tip custom-block"><p class="custom-block-title">Default Notifications</p><p>By default SQS sends all new locations and readings to the target SQS queue.</p></div><h2 id="_3-confirmation" tabindex="-1">3. Confirmation <a class="header-anchor" href="#_3-confirmation" aria-label="Permalink to &quot;3. Confirmation&quot;">​</a></h2><p>After registering, AWS SNS will send a <code>SubscriptionConfirmation</code> message to your SQS queue. <strong>You must confirm the subscription</strong> by visiting the <code>SubscribeURL</code> in the message. This step is required by AWS and is not automatic.</p><ul><li>Retrieve the <code>SubscriptionConfirmation</code> message from your SQS queue.</li><li>Visit the <code>SubscribeURL</code> in a browser or with a tool like <code>curl</code>.</li><li>Once confirmed, notifications will start arriving in your queue.</li></ul><p>If you do not confirm, no further messages will be delivered.</p><h2 id="_4-notification" tabindex="-1">4. Notification <a class="header-anchor" href="#_4-notification" aria-label="Permalink to &quot;4. Notification&quot;">​</a></h2><p>Once confirmed, you&#39;ll receive notifications from SNS.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><strong>No confirmation message?</strong><ul><li>Double-check your SQS policy and ARN.</li><li>Ensure the queue is in the correct AWS region.</li><li>Make sure the trigger registration succeeded.</li></ul></li><li><strong>Still not working?</strong><ul><li>Contact support with your account name, SQS ARN and device ID for assistance.</li></ul></li></ul>`,23)])])}const q=s(o,[["render",n]]);export{h as __pageData,q as default};
